package shipping;

import static readcode.Assert.*;

import java.io.IOException;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class LabelWorkerTest {
    private InMemoryQueue queue;
    private final List<String> printed = new ArrayList<>();
    private final Set<String> down = new HashSet<>();
    private LabelWorker worker;

    public void setUp() {
        queue = new InMemoryQueue();
        worker = new LabelWorker(queue, orderId -> {
            if (down.contains(orderId)) throw new IOException("printer offline");
            printed.add(orderId);
        });
    }

    public void testSuccessfulMessageIsPrintedAndAcked() {
        queue.publish("A-1");
        assertTrue(worker.pollOnce());
        assertEquals(List.of("A-1"), printed);
        assertEquals(0, queue.readyCount());
        assertEquals(0, queue.inFlightCount());
    }

    public void testEmptyQueueReturnsFalse() {
        assertFalse(worker.pollOnce());
    }

    public void testFailedMessageGoesBackToTheQueue() {
        queue.publish("A-1");
        down.add("A-1");
        worker.pollOnce();
        System.out.println("after a failed print: ready=" + queue.readyCount() + " inFlight=" + queue.inFlightCount()
                + " failures=" + worker.failures());
        assertEquals(1, queue.readyCount(), "the failed order must be redelivered");
        assertEquals(0, queue.inFlightCount());
    }

    public void testFailureIsRecordedWithAttemptNumber() {
        queue.publish("A-1");
        down.add("A-1");
        worker.pollOnce();
        assertEquals(List.of("order A-1 attempt 1: printer offline"), worker.failures());
    }

    public void testRedeliveredMessageIsPrintedOnceThePrinterIsBack() {
        queue.publish("A-1");
        queue.publish("A-2");
        down.add("A-1");
        worker.drain(2);
        down.clear();
        worker.drain(10);
        assertEquals(List.of("A-2", "A-1"), printed);
        assertEquals(0, queue.readyCount());
    }

    public void testRedeliveryCarriesAHigherAttemptNumber() {
        queue.publish("A-1");
        down.add("A-1");
        worker.drain(3);
        assertEquals(3, worker.failures().size());
        assertTrue(worker.failures().get(2).contains("attempt 3"), "got " + worker.failures());
    }

    public void testDrainHandlesEveryMessage() {
        for (int i = 0; i < 5; i++) queue.publish("B-" + i);
        assertEquals(5, worker.drain(100));
        assertEquals(5, printed.size());
    }
}
